// Same finite-state transitions and ancestral TT draws as attention_core.py.
// Uniform random numbers are generated by NumPy PCG64 in the original order.
// This loop exposes actual events; it never uses a noise or expectation proxy.
#include <cstdint>
#include <algorithm>
extern "C" {
void fsm_trace(int16_t *state, const uint8_t *bits, int16_t *trace,
               int64_t count, int32_t width, int32_t states) {
  for (int32_t t=0;t<width;t++) {
    for (int64_t i=0;i<count;i++) {
      int s=state[i]+(bits[int64_t(t)*count+i] ? 1 : -1);
      state[i]=std::min(std::max(s,0),states-1);
      if (trace) trace[int64_t(t)*count+i]=state[i];
    }
  }
}
void categorical_trace(const int16_t *state, const double *uniform,
             const double *cdf, const int32_t *right_size,
             uint8_t *event, int32_t *counts, int64_t rows, int32_t width,
             int32_t states, int32_t n, int32_t pad) {
  const int64_t count=rows*width;
  for (int64_t e=0;e<count;e++) {
    int bond=0;
    for (int j=0;j<n;j++) {
      const double *p=cdf+((int64_t(j)*states+state[e*n+j])*pad+bond)*pad;
      const double u=uniform[int64_t(j)*count+e];
      int lo=0,hi=right_size[j];
      while (lo<hi) {
        const int mid=(lo+hi)/2;
        if (p[mid]<u) lo=mid+1; else hi=mid;
      }
      bond=std::min(lo,right_size[j]-1);
    }
    event[e]=uint8_t(bond);
    counts[(e%rows)*n+bond]++;
  }
}
}
